CREATE TABLE `jobs` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`workflow_id` integer NOT NULL,`status` text NOT NULL,`start_time` datetime,`end_time` datetime,`podcasts_processed` integer DEFAULT 0,`episodes_found` integer DEFAULT 0,`episodes_created` integer DEFAULT 0,`episodes_matched` integer DEFAULT 0,`error_count` integer DEFAULT 0,`triggered_by` text DEFAULT "cron",`compensation_of_job_id` integer,`compensated_by_job_id` integer,CONSTRAINT `fk_workflows_jobs` FOREIGN KEY (`workflow_id`) REFERENCES `workflows`(`id`));
CREATE TABLE `job_executions` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`job_id` integer NOT NULL,`podcast_id` integer,`podcast_title` text,`podcast_feed_url` text,`status` text NOT NULL,`episodes_found` integer DEFAULT 0,`episodes_created` integer DEFAULT 0,`episodes_matched` integer DEFAULT 0,`error_message` text,`log_info` text,`processing_time` integer DEFAULT 0,`feed_http_status` integer,`feed_error_category` text NOT NULL DEFAULT "not_observed",`feed_target_domain` text NOT NULL DEFAULT "",`feed_response_time_ms` integer NOT NULL DEFAULT 0,`feed_retry_after` text NOT NULL DEFAULT "",`feed_etag` text NOT NULL DEFAULT "",`feed_last_modified` text NOT NULL DEFAULT "",`feed_cache_control` text NOT NULL DEFAULT "",`feed_expires` text NOT NULL DEFAULT "",`feed_age` text NOT NULL DEFAULT "",`feed_response_bytes` integer NOT NULL DEFAULT 0,`feed_source_type` text NOT NULL DEFAULT "unknown",`feed_source_url` text NOT NULL DEFAULT "",`feed_identity_verification` text NOT NULL DEFAULT "not_checked",`feed_cache_status` text NOT NULL DEFAULT "not_used",`feed_freshness` text NOT NULL DEFAULT "unknown",`feed_egress_id` text NOT NULL DEFAULT "unknown",`feed_snapshot_retrieved_at` datetime,`feed_circuit_state` text NOT NULL DEFAULT "not_used",`feed_failure_phase` text NOT NULL DEFAULT "",`feed_user_agent_gate_state` text NOT NULL DEFAULT "",`feed_user_agent_probe_result` text NOT NULL DEFAULT "",`feed_user_agent_approved_by` text NOT NULL DEFAULT "",`feed_user_agent_approved_at` datetime,`feed_user_agent_last_probe_at` datetime,CONSTRAINT `fk_jobs_executions` FOREIGN KEY (`job_id`) REFERENCES `jobs`(`id`));
CREATE TABLE `job_feed_attempts` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`job_id` integer NOT NULL,`podcast_id` integer NOT NULL,`attempt_no` integer NOT NULL DEFAULT 1,`source_type` text NOT NULL DEFAULT "primary",`attempted_at` datetime NOT NULL,`http_status` integer,`error_category` text NOT NULL DEFAULT "not_observed",`failure_phase` text NOT NULL DEFAULT "",`retry_decision` text NOT NULL DEFAULT "",`identity_verification` text NOT NULL DEFAULT "not_checked",`target_domain` text NOT NULL DEFAULT "",`source_url` text NOT NULL DEFAULT "",`is_final_result` numeric NOT NULL DEFAULT false,`derived_policy` numeric NOT NULL DEFAULT false,`feed_user_agent_gate_state` text NOT NULL DEFAULT "",`feed_user_agent_probe_result` text NOT NULL DEFAULT "",`feed_user_agent_approved_by` text NOT NULL DEFAULT "",`feed_user_agent_approved_at` datetime,`feed_user_agent_last_probe_at` datetime);
CREATE TABLE `scheduler_runs` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`workflow_id` integer NOT NULL,`status` text NOT NULL,`scheduled_at` datetime NOT NULL,`started_at` datetime,`completed_at` datetime,`duration` integer,`reason` text,`job_id` integer);
CREATE TABLE `reports` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`job_id` integer NOT NULL,`title` text NOT NULL,`content` text NOT NULL,`summary` text,`episodes_count` integer DEFAULT 0,`podcasts_count` integer DEFAULT 0,`matched_count` integer DEFAULT 0,`time_range_start` datetime,`time_range_end` datetime,`time_range_mode` text,`generated_at` datetime NOT NULL,`format` text DEFAULT "markdown",`file_size` integer DEFAULT 0,`publish_to_homepage` numeric NOT NULL DEFAULT false,`report_type` text NOT NULL DEFAULT "",`workflow_name` text NOT NULL DEFAULT "",`structured_episodes` json,`llm_summary` text,`llm_model_used` text,`llm_tokens_used` integer DEFAULT 0,`llm_error` text);
CREATE TABLE feed_snapshots (
    feed_url          TEXT PRIMARY KEY,
    retrieved_at      INTEGER NOT NULL,
    fingerprint       TEXT NOT NULL,
    raw_content       BLOB NOT NULL,
    content_length    INTEGER NOT NULL,
    etag              TEXT NOT NULL DEFAULT '',
    last_modified     TEXT NOT NULL DEFAULT '',
    validated_at      INTEGER NOT NULL,
    source_at_capture TEXT NOT NULL DEFAULT ''
);
CREATE TABLE feed_user_agent_gates (
    domain                   TEXT NOT NULL,
    user_agent_fingerprint   TEXT NOT NULL,
    state                    TEXT NOT NULL DEFAULT 'blocked',
    detected_at              INTEGER NOT NULL,
    probe_eligible_at        INTEGER NOT NULL,
    last_probe_result        TEXT NOT NULL DEFAULT '',
    recovery_success_count   INTEGER NOT NULL DEFAULT 0,
    updated_at               INTEGER NOT NULL, approved_by TEXT NOT NULL DEFAULT '', approved_at INTEGER, last_probe_at INTEGER,
    PRIMARY KEY (domain, user_agent_fingerprint)
);
CREATE TABLE feed_user_agent_gate_audits (
    id                       INTEGER PRIMARY KEY AUTOINCREMENT,
    domain                   TEXT NOT NULL,
    user_agent_fingerprint   TEXT NOT NULL,
    action                   TEXT NOT NULL,
    mode                     TEXT NOT NULL,
    actor                    TEXT NOT NULL DEFAULT '',
    result                   TEXT NOT NULL DEFAULT '',
    created_at               INTEGER NOT NULL
);
CREATE TABLE feed_user_agent_gate_recovery_feeds (
    domain                   TEXT NOT NULL,
    user_agent_fingerprint   TEXT NOT NULL,
    feed_fingerprint         TEXT NOT NULL,
    status                   TEXT NOT NULL DEFAULT 'in_flight',
    first_observed_at        INTEGER NOT NULL,
    last_success_at          INTEGER,
    PRIMARY KEY (domain, user_agent_fingerprint, feed_fingerprint)
);
CREATE TABLE `episode_audio_assets` (`id` integer PRIMARY KEY AUTOINCREMENT,`episode_id` integer NOT NULL,`source_digest` text NOT NULL,`status` text NOT NULL,`relative_path` text NOT NULL DEFAULT "",`sha256` text NOT NULL DEFAULT "",`size_bytes` integer NOT NULL DEFAULT 0,`duration_seconds` integer NOT NULL,`media_type` text NOT NULL DEFAULT "",`extension` text NOT NULL DEFAULT "",`error_code` text NOT NULL DEFAULT "",`error_message` text NOT NULL DEFAULT "",`claim_token` text NOT NULL DEFAULT "",`claim_expires_at` datetime,`queued_at` datetime NOT NULL,`downloading_at` datetime,`ready_at` datetime,`failed_at` datetime,`created_at` datetime NOT NULL,`updated_at` datetime NOT NULL,CONSTRAINT `fk_episode_audio_assets_episode` FOREIGN KEY (`episode_id`) REFERENCES `episodes`(`id`) ON DELETE CASCADE,CONSTRAINT `chk_episode_audio_asset_status` CHECK (status IN ('queued','downloading','ready','failed')));
