CREATE TABLE `processing_schedule_runs` (`id` integer PRIMARY KEY AUTOINCREMENT,`trigger_key` text NOT NULL,`scheduled_for` datetime NOT NULL,`cron_expression` text NOT NULL,`timezone` text NOT NULL,`batch_size` integer NOT NULL,`status` text NOT NULL,`candidate_count` integer NOT NULL DEFAULT 0,`started_count` integer NOT NULL DEFAULT 0,`skipped_count` integer NOT NULL DEFAULT 0,`error_code` text NOT NULL DEFAULT "",`error_message` text NOT NULL DEFAULT "",`finished_at` datetime,`created_at` datetime NOT NULL,`updated_at` datetime NOT NULL,CONSTRAINT `chk_processing_schedule_status` CHECK (status IN ('running','completed','failed')));
