CREATE TABLE `processing_schedule_items` (`id` integer PRIMARY KEY AUTOINCREMENT,`schedule_run_id` integer NOT NULL,`episode_id` integer NOT NULL,`queue_position` integer NOT NULL,`outcome` text NOT NULL,`reason` text NOT NULL DEFAULT "",`processing_run_id` integer,`created_at` datetime NOT NULL,`updated_at` datetime NOT NULL,CONSTRAINT `chk_processing_schedule_item_outcome` CHECK (outcome IN ('started','skipped')));
